 isRequired:{type:'boolean'},isActive:{type:'boolean'},isVisible:{type:'boolean'},displayOrder:{type:'integer',minimum:0,maximum:10000},
 configuration:{type:'object',additionalProperties:false,properties:{placeholder:{type:'string',maxLength:150},helpText:{type:'string',maxLength:500},maxLength:{type:'integer',minimum:1,maximum:4000},pages:{type:'array',uniqueItems:true,items:{type:'string',enum:Object.keys(require('./field-registry').PAGES)}}}},
 options:{type:'array',maxItems:100,items:{$ref:'#/components/schemas/ConfigurableOption'}},
