add('/api/configurable-fields/{id}/editor','put','Atomically save inline field label, settings and complete option order',{type:'object',additionalProperties:false,required:['version','data'],properties:{version:{type:'integer',minimum:1},data:{type:'object',additionalProperties:false,properties:{...fieldPatch.properties,options:{type:'array',maxItems:100,items:{type:'object',additionalProperties:false,required:['value','label'],properties:{id:str,value:schemas.ConfigurableOption.properties.value,label:schemas.ConfigurableOption.properties.label,isActive:{type:'boolean'},archived:{type:'boolean'}}}}}}}},{description:'Requires fields.manage and CSRF. All existing option IDs must be retained exactly once. Existing values/IDs and field identity are immutable. Mark archived options explicitly; never omit them. One transaction, one version/revision increment, one before/after audit. Protected fields reject writes; label-only fields accept label only.'});
schemas.QuotationExport={type:'object',additionalProperties:false,properties:{type:{type:'string',enum:['quotation','customer','custom'],default:'quotation'},scope:{type:'string',enum:['selected','filtered','all'],default:'filtered'},columns:{type:'array',minItems:1,maxItems:20,uniqueItems:true,items:str,description:'Ordered column keys returned by export/options. Quotation Details accepts quotation columns; Customer Details accepts customer columns plus number when quotationWise is true; Custom Field Selection accepts both. Customer columns require customer.view.'},selectedIds:{type:'array',maxItems:1000,uniqueItems:true,items:str},quotationWise:{type:'boolean',default:false},filters:{type:'object',additionalProperties:false,properties:Object.fromEntries(require('../shared/quotation-filters').keys.map(key=>[key,str]))}}};
add('/api/quotation-export/options','get','Available quotation CSV columns, defaults and limits',null,{description:'Requires quotation.view_all or quotation.view_own. Customer contact columns are returned only with customer.view. One company per database; no tenant parameters.'});
add('/api/quotation-list','get','Read one authorized quotation page',null,{description:'Requires quotation.view_all or quotation.view_own. GET parameters: page (positive integer, maximum 999999999), pageSize (10,20,30,40; default 10), plus the QuotationExport filter keys. Unknown/duplicate parameters and invalid filters are rejected. Customer-category filtering requires customer.view. Returns data, display (stored GST-inclusive integer-paise total and permitted customer labels), applied filters and pagination {page,pageSize,total,totalPages,from,to}. Empty lists use page 1 of 1 and range 0-0. Out-of-range pages clamp to the last page. Count, rows, items and history use one repeatable-read snapshot; position then ID preserves workspace order. Company isolation follows the authenticated database and owner scope. No tenant parameter.'});
add('/api/quotation-export/preview','post','Count every matching export row across all pages',ref('QuotationExport'),{description:'Requires quotation view permission and CSRF. Own-only permissions restrict all three scopes. Customer Details deduplicates customers unless quotationWise is true. Selected/all scope intentionally ignores filters. Invalid or inaccessible selected records fail closed.'});
add('/api/quotation-export/csv','post','Download a bounded, safely escaped quotation/customer CSV',ref('QuotationExport'),{description:'Same authorization, validation and scope as preview. At most 50,000 rows, 100 MiB and 1,000 selected IDs. At most two downloads per application worker and one per user; busy requests return 429. Streams a privately staged file after coherent database-snapshot validation. UTF-8 BOM, CRLF, formula protection, DD/MM/YYYY dates and exact decimal INR totals including GST. Active delivery addresses share a newline-separated cell. Customer data comes from current relationships; quotation customer/company use historical snapshots when present.',mime:'text/csv',response:{type:'string'}});
module.exports = { openapi: '3.1.0', info: { title: 'Design Paradise API', version: '3.2.0', description: 'Single-company quotation backend with backend-enforced configurable permissions and immutable creator scopes. Uses cookie sessions and X-CSRF-Token for writes. Catalog/charges use INR decimal amounts; computed amounts use integer paise. WhatsApp manual click-to-chat prepares an authenticated PDF and records honest manual results; automated provider delivery is not configured. Public hosting and outbound email are separate infrastructure integrations.' }, servers: [{ url: '/' }], paths, components: { securitySchemes: { session: { type: 'apiKey', in: 'cookie', name: 'paradise_session' }, csrf: { type: 'apiKey', in: 'header', name: 'X-CSRF-Token' } }, schemas } };
